-- BEACH1B V1 (2026-11-23, Claude): Exile's Reach camp quests 59932 Cooking Meat / 59933 Enhanced Combat Tactics (spar with Warlord Breka Grimaxe).
-- Data from LoreWalkerTDB (12.x) re-built for AC 3.3.5; models are 3.3.5 stand-ins; Chinese text is Claude's own.
-- Safe to run twice. guids = live legal maximum + 1 (must stay below 16777215). Keep worldserver stopped.
SET @spawn_limit := 16777215;

DELETE FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1B %';
DELETE FROM `gameobject` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1B %';
DELETE FROM `creature_template` WHERE `entry` IN (164577,161130,161131,161133);
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (164577,161130,161131,161133);
DELETE FROM `creature_loot_template` WHERE `Entry` IN (161130,161131,161133);
DELETE FROM `item_template` WHERE `entry` IN (174072, 174074);
DELETE FROM `gameobject_template` WHERE `entry` = 9174074;
DELETE FROM `quest_template` WHERE `ID` IN (59932, 59933);
DELETE FROM `quest_template_addon` WHERE `ID` IN (59932, 59933);
DELETE FROM `quest_offer_reward` WHERE `ID` IN (59932, 59933);
DELETE FROM `quest_request_items` WHERE `ID` IN (59932, 59933);
DELETE FROM `creature_queststarter` WHERE `quest` IN (59932, 59933);
DELETE FROM `creature_questender` WHERE `quest` IN (59932, 59933);
SELECT COALESCE(MAX(`guid`), 0) INTO @g FROM `creature` WHERE `guid` < @spawn_limit;
SELECT COALESCE(MAX(`guid`), 0) INTO @go FROM `gameobject` WHERE `guid` < @spawn_limit;






SELECT IF(@g + 46 + 10000 < @spawn_limit AND @go + 1 + 10000 < @spawn_limit, 'guid base OK', 'ABORT: no guid room, do not continue') AS guid_check, @g AS legal_max_creature_guid, @go AS legal_max_go_guid;








SELECT `guid`, `id1`, `position_x`, `position_y`, `position_z` FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1B fixed' ORDER BY `guid`;
SELECT COUNT(*) AS beach1b_creatures FROM `creature` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1B %';
SELECT `guid`, `id`, `position_x`, `position_y`, `position_z` FROM `gameobject` WHERE `map` = 12175 AND `Comment` LIKE 'BEACH1B %';
SELECT MAX(`guid`) AS max_creature_guid_after, SUM(`guid` >= @spawn_limit) AS invalid_after FROM `creature`;
