INSERT INTO `gameobject` (`guid`, `id`, `map`, `zoneId`, `areaId`, `spawnMask`, `phaseMask`, `position_x`, `position_y`, `position_z`, `orientation`, `rotation0`, `rotation1`, `rotation2`, `rotation3`, `spawntimesecs`, `animprogress`, `state`, `ScriptName`, `VerifiedBuild`, `Comment`) VALUES (@go + 1, 9174074, 12175, 0, 0, 1, 1, -246.5, -2490.0, 18.19, 0, 0, 0, 0, 1, 300, 100, 1, '', 0, 'BEACH1B campfire');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `RewardItem1`, `RewardAmount1`, `RequiredItemId1`, `RequiredItemCount1`, `RequiredItemId2`, `RequiredItemCount2`, `ObjectiveText1`, `ObjectiveText2`) VALUES (59932, 2, 1, 1, 2, 0, 'Cooking Meat / 烹饪肉', 'Get 5 Raw Meat from wildlife around the Abandoned Camp, then cook it on the campfire. / 从废弃营地周围的野兽身上取得5份生肉，然后在篝火上烤熟。', 'This is Won''sa, a shaman who was with the expedition.$B$BShe is dying of starvation. A death unfit for the Horde!$B$BSlay some of the nearby wildlife for their meat and cook it over the fire.$B$BWon''sa can tell us what happened to the missing expedition after she eats.$B$B这是旺萨，一名与远征队同行的萨满。$B$B她快要饿死了！这样的死法配不上部落！$B$B去杀一些附近的野兽取肉，在火上烤熟。$B$B旺萨吃饱之后，就能告诉我们失踪的远征队出了什么事。', 'Give Won''sa the cooked meat. / 把烤熟的肉交给旺萨。', '', 117, 4, 174072, 5, 174074, 1, 'Raw Meat collected from wildlife / 从野兽身上取得的生肉', 'Cook the meat on the campfire / 在篝火上烤肉');
INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `RewardXPDifficulty`, `Flags`, `LogTitle`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `AreaDescription`, `RequiredNpcOrGo1`, `RequiredNpcOrGoCount1`, `ObjectiveText1`) VALUES (59933, 2, 1, 1, 2, 0, 'Enhanced Combat Tactics / 强化战斗战术', 'Spar with Warlord Grimaxe. / 与战争领主格里马克斯切磋。', 'Won''sa said the quilboar have kidnapped the missing expedition.$B$BThe quilboar will kill you if you''re not prepared. They''re much smarter and deadlier than murlocs.$B$BI won''t see you die by their hands. We''re going to spar one last time.$B$BWhen we are done, you will cleave a path straight through the quilboar!$B$B旺萨说野猪人绑架了失踪的远征队。$B$B如果你没有准备好，野猪人会杀了你。它们比鱼人聪明得多，也危险得多。$B$B我不会眼睁睁看你死在它们手里。我们最后再切磋一次。$B$B等我们打完，你就能一路砍穿那些野猪人！', 'Spar with Warlord Grimaxe. / 与战争领主格里马克斯切磋。', '', 164577, 1, 'Abilities proven against Warlord Grimaxe / 已在战争领主格里马克斯面前证明实力');
