INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES (59932, 0, 0, 'Please... I need food.$B$B求求你……我需要食物。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59932, 1, 0, 0, 0, 'Thank you, friend. I feel my strength returning.$B$B谢谢你，朋友。我感觉力气回来了。', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `EmoteDelay1`, `EmoteDelay2`, `RewardText`, `VerifiedBuild`) VALUES (59933, 1, 0, 0, 0, 'Well fought. The quilboar will not know what hit them.$B$B打得好。野猪人根本不知道是什么打了它们。', 0);
